  void Dig(string name,int x,int y)
  {
   var d=env.State.Discovery;int before=d.Remembered.Count;long queries=env.State.World.Queries;long t=System.Diagnostics.Stopwatch.GetTimestamp();int changes=live.Stream.Dig(new List<DualTile>{new DualTile(env.State.Fixture.X+x,env.State.Fixture.Y+y)});env.Process(1.0/60,false);result.events.Add(new Event{name=name,elapsed=StreamingGeometry.Elapsed(t),physicalMs=live.Stream.DigMs,discoveryMs=env.DiscoveryMs,newMemory=d.Remembered.Count-before,visits=d.LastVisits,physicalRevision=env.State.World.Revision,changedChunks=live.Stream.LastDigRebuilds,queries=env.State.World.Queries-queries});Check(changes==1,"Real physical excavation: "+name);
  }
  IEnumerator Settle(){int n=0;do{env.Process(1.0/60,false);yield return null;if(n++>2500){Check(false,"Readiness/reveal timeout");yield break;}}while(!live.Ready||live.Stream.PendingPresentation>0||env.State.Discovery.PendingReleases>0);for(int i=0;i<5;i++)yield return null;}
  IEnumerator Frames(string name,int frames,Vector2 movement,bool model=true)
  {phase=name;previous=Time.realtimeSinceStartupAsDouble;for(int n=0;n<frames;n++){if(live.Ready&&movement.sqrMagnitude>0)live.Step(movement,Vector2.right,false,1f/60);if(model)env.Process(1.0/60);if(!env.Lab.paused)env.Lab.Advance(1.0/60);foreach(var actor in env.HiddenActors)actor.Step(new Point2(live.Position.x,live.Position.y),live.LogicalVisible,1.0/60,live.World);FrameTimingManager.CaptureFrameTimings();yield return null;Record();}}
  IEnumerator Drive(Point2 target,string name)
  {int n=0;while(Vector2.Distance(live.Position,V(target))>.09f&&n++<4000){var delta=V(target)-live.Position;yield return Frames(name,1,Vector2.ClampMagnitude(delta/(5f/60),1));}Check(n<4000,"Physical movement along network to "+target.X+","+target.Y);}
  void Record()
  {
   double now=Time.realtimeSinceStartupAsDouble;var f=new Frame{phase=phase,interval=(now-previous)*1000,host=live.DisplayMs,discovery=env.DiscoveryMs,presentation=env.PresentationMs,maskRebuild=live.Stream.PresentationMs,main=main.Valid?main.LastValue*1e-6:-1,allocated=allocation.Valid?allocation.LastValue:-1,ready=live.Ready,residents=live.Stream.Resident.Count,pendingMasks=live.Stream.PendingPresentation,remembered=env.State.Discovery.Remembered.Count,visual=env.State.Discovery.Visual.Count,buffers=live.Gpu.BufferCount,materials=live.Gpu.ResourceCount,pooled=live.Stream.PooledData,presentations=live.PooledPresentations,managed=result.frames.Count%30==0?GC.GetTotalMemory(false):0,unityMemory=result.frames.Count%30==0?UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong():0};if(FrameTimingManager.GetLatestTimings(1,timings)>0&&timings[0].frameStartTimestamp!=timestamp){timestamp=timings[0].frameStartTimestamp;f.cpu=timings[0].cpuFrameTime;f.gpu=timings[0].gpuFrameTime;}result.frames.Add(f);previous=now;
  }
